package android.os;import java.util.*;public final class Parcel {private final List<Object> values=new ArrayList<Object>();private int at;public static Parcel obtain(){return new Parcel();}public void recycle(){}public void writeInterfaceToken(String s){values.add(s);}public void enforceInterface(String s){if(!s.equals(readString()))throw new IllegalArgumentException("interface");}public void writeString(String s){values.add(s);}public String readString(){return (String)values.get(at++);}public void writeInt(int n){values.add(n);}public int readInt(){return (Integer)values.get(at++);}public void writeStrongBinder(IBinder b){values.add(b);}public IBinder readStrongBinder(){return (IBinder)values.get(at++);}public void fixtureObject(Object o){values.add(o);}public Object fixtureObject(){return values.get(at++);}public int dataAvail(){return values.size()-at;}}